import E3 from "eventemitter3";

//#region src/base/buffer.d.ts
/**
* 消息操作类型
*/
/**
 * 消息操作类型
 */
declare enum WS_OP {
  HEARTBEAT = 2,
  HEARTBEAT_REPLY = 3,
  MESSAGE = 5,
  USER_AUTHENTICATION = 7,
  CONNECT_SUCCESS = 8,
  Unknown = -1,
}
/**
 * 协议版本
 */
declare enum WS_BODY_PROTOCOL_VERSION {
  NORMAL = 0,
  NUMBER = 1,
  ZLIB = 2,
  BROTLI = 3,
}
interface ProtocolHeader {
  op: WS_OP;
  ver: WS_BODY_PROTOCOL_VERSION;
  packetLength: number;
  headerLength: number;
  sequence: number;
}
declare function serialize(type: WS_OP, data?: string | Record<string, any>): Uint8Array; //#endregion
//#region src/base/types.d.ts
type BILIBILI_HOST = string;
type PartialByKeys<O extends Record<string, any>, U = keyof O, UU = (U extends keyof O ? U : never), PO = Partial<Pick<O, UU>>> = PO & { [K in keyof O as K extends U ? never : K]: O[K] };
type RequiredByKeys<O extends Record<string, any>, U = keyof O, UU = (U extends keyof O ? U : never), PO = Required<Pick<O, UU>>> = PO & Omit<O, UU>;
type Merge<A, B> = { [K in keyof A | keyof B]: K extends keyof A & keyof B ? A[K] | B[K] : K extends keyof B ? B[K] : K extends keyof A ? A[K] : never };
type Nullable<T> = null | undefined | T;
interface ISocket {
  type: 'tcp';
  write: (data: Uint8Array) => void;
  end: () => void;
  reconnect: () => void;
}
interface IWebSocket {
  type: 'websocket';
  send: (data: Uint8Array) => void;
  close: () => void;
  reconnect: () => void;
}
type Options = PartialByKeys<WSOptions, keyof AuthOptions | keyof ConnectionOptions>;
interface BaseLiveClientOptions<B extends Uint8Array> extends Options {
  socket: ISocket | IWebSocket;
  room: number | string;
  zlib: IZlib<B>;
}
interface BaseOptions {
  /**
   * 是否获取原始消息
   * @default false
   */
  raw?: boolean;
  /**
   * 是否获取全部信息
   *  如果关闭 stub, 监听 `msg` 消息将不生效
   * @default true
   */
  stub?: boolean;
  /**
   * 保持连接, 当发生错误和断开连接时自动重新连接
   * @default true
   */
  keepalive?: boolean;
  /**
   * 重新连接到服务器的时间间隔
   * @default 5000
   */
  reconnectTime?: number;
  /**
   * 心跳时间
   * @default 300000
   */
  heartbeatTime?: number;
}
interface AuthOptions {
  authBody?: Uint8Array;
  key?: any;
}
interface ConnectionOptions {
  url?: string;
  host?: BILIBILI_HOST;
  port?: number;
  path?: string;
}
interface CustomWebSocket {
  (url: string): WebSocket | Promise<WebSocket>;
}
interface WSOptions extends BaseOptions, AuthOptions, ConnectionOptions {
  headers?: {
    [key: string]: string;
  } | undefined;
  ssl?: boolean;
  platform?: 'web' | string;
  protover?: 1 | 2 | 3;
  uid?: number;
  type?: number;
  key?: string;
  buvid?: string;
  customWebSocket?: CustomWebSocket;
}
interface MessageMeta extends ProtocolHeader {}
interface Message<T> {
  meta: MessageMeta;
  data: T;
}
interface IZlib<T extends Uint8Array = Uint8Array> {
  inflateAsync: (v: T) => Promise<T>;
  brotliDecompressAsync: (v: T) => Promise<T>;
} //#endregion
